<!doctype html><html lang="<?=$en?'en':'vi'?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=$en?'Stay booking':'Tra cứu đơn phòng'?></title><link rel="stylesheet" href="/assets/site.css"><script src="/assets/stay-lookup.js" defer></script></head><body><main class="section lookup-panel" id="stay-lookup" data-locale="<?=$en?'en':'vi'?>"><h1><?=$en?'Stay booking':'Tra cứu đơn phòng'?></h1><form id="stay-lookup-form" class="quote-form"><fieldset><label><?=$en?'Booking code':'Mã đơn phòng'?><input name="code" required pattern="JH[A-F0-9]{10}" maxlength="12"></label><label><?=$en?'Private access key':'Khóa tra cứu riêng'?><input name="accessKey" type="password" required pattern="[a-f0-9]{64}" minlength="64" maxlength="64" autocomplete="off"></label><button class="button" type="submit"><?=$en?'Find booking':'Tra cứu'?></button></fieldset></form><p id="stay-lookup-status" role="status"></p><section id="stay-booking-details"></section><p><?=$en?'Keep your booking link private.':'Giữ kín liên kết và khóa tra cứu đơn.'?></p></main></body></html>
